// Checkout.test.tsx
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { Checkout } from './Checkout';
import { CartProvider } from './CartContext';
import { PaymentProvider } from './PaymentContext';

// Test wrapper with providers
const renderCheckout = (props = {}, cartItems = [{ id: '1', name: 'Item', price: 29.99 }]) => {
  const mockCart = { items: cartItems, total: 29.99, clearCart: vi.fn() };
  const mockPayment = { processPayment: vi.fn().mockResolvedValue({ orderId: 'ORD-123' }) };

  return {
    ...render(
      <CartProvider value={mockCart}>
        <PaymentProvider value={mockPayment}>
          <Checkout {...props} />
        </PaymentProvider>
      </CartProvider>
    ),
    mockCart,
    mockPayment
  };
};

describe('Checkout - Happy Path', () => {
  it('completes full checkout flow from shipping to confirmation', async () => {
    const user = userEvent.setup();
    const onComplete = vi.fn();
    renderCheckout({ onComplete });

    // Shipping step
    await user.type(screen.getByLabelText(/street address/i), '123 Main St');
    await user.type(screen.getByLabelText(/city/i), 'Toledo');
    await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
    await user.type(screen.getByLabelText(/zip code/i), '90210');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Payment step
    await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
    await user.type(screen.getByLabelText(/expiry/i), '12/25');
    await user.type(screen.getByLabelText(/cvv/i), '123');
    await user.type(screen.getByLabelText(/name on card/i), 'Max Klinger');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Review & place order
    expect(screen.getByRole('region', { name: /order review/i })).toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: /place order/i }));

    // Confirmation
    await waitFor(() => {
      expect(screen.getByRole('status', { name: /order confirmation/i })).toBeInTheDocument();
    });
    expect(onComplete).toHaveBeenCalledWith('ORD-123');
  });
});

describe('Form Validation', () => {
  it('shows error for invalid ZIP code', async () => {
    const user = userEvent.setup();
    renderCheckout();

    await user.type(screen.getByLabelText(/zip code/i), 'bad');
    await user.click(screen.getByRole('button', { name: /continue/i }));

    expect(screen.getByRole('alert')).toHaveTextContent(/valid zip code/i);
    expect(screen.getByLabelText(/zip code/i)).toHaveAttribute('aria-invalid', 'true');
  });

  it('validates card number format', async () => {
    const user = userEvent.setup();
    renderCheckout();
    // Navigate to payment...
    await user.type(screen.getByLabelText(/card number/i), '123');
    await user.click(screen.getByRole('button', { name: /review/i }));

    expect(screen.getByText(/valid 16-digit/i)).toBeInTheDocument();
  });
});

describe('Edge Cases', () => {
  it('shows empty cart message when no items', () => {
    renderCheckout({}, []);
    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
  });

  it('displays payment error and allows retry', async () => {
    const user = userEvent.setup();
    const { mockPayment } = renderCheckout();
    mockPayment.processPayment.mockRejectedValueOnce(new Error('Card declined'));
    // Complete to review, click place order...

    await waitFor(() => {
      expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
    });
    expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
  });

  it('disables buttons during payment processing', async () => {
